private static void backTrack(int sumPrice, int depth) {
    if (sumPrice >= minPriceSum) {
        return;
    }

    if (depth == N) {
        minPriceSum = sumPrice;
        return;
    }

    for (int i = 0; i < N; i++) {
        if (!visited[i]){
            visited[i] = true;
            backTrack(sumPrice + graph[depth][i], depth + 1);
            visited[i] = false;
        }
    }
}
